namespace putgd {
HistoryWindow::HistoryWindow(HistoryService& history,OperationService& operations,QWidget* parent):QWidget(parent),history_(history),operations_(operations){setWindowTitle("put.gd — Upload history");resize(1000,700);auto* layout=new QVBoxLayout(this);auto* filters=new QGridLayout;layout->addLayout(filters);auto* search=new QLineEdit(this);search->setObjectName("historySearch");search->setMaxLength(256);search->setPlaceholderText("Search stored name");filters->addWidget(search,0,0,1,3);auto* filter=new QPushButton("Search",this);filters->addWidget(filter,0,3);
 QHash<QString,QLineEdit*> fields;int filterIndex=0;for(auto key:QStringList{"from","to","mime","profileId","uploadStatus","localStatus","remoteStatus"}){auto* e=new QLineEdit(this);e->setObjectName("historyFilter"+key);e->setPlaceholderText(key);filters->addWidget(e,1+filterIndex/4,filterIndex%4);++filterIndex;fields[key]=e;}
 model_=new HistoryModel(history_,this);table_=new QTableView(this);table_->setObjectName("historyTable");table_->setModel(model_);table_->setSelectionBehavior(QAbstractItemView::SelectRows);table_->setSelectionMode(QAbstractItemView::ExtendedSelection);table_->horizontalHeader()->setSectionResizeMode(QHeaderView::ResizeToContents);layout->addWidget(table_);count_=new QLabel(this);layout->addWidget(count_);auto* paging=new QHBoxLayout;layout->addLayout(paging);auto* previous=new QPushButton("Previous page",this);auto* next=new QPushButton("Next page",this);paging->addWidget(previous);paging->addWidget(next);auto* refreshButton=new QPushButton("Refresh",this);paging->addWidget(refreshButton);
 auto apply=[this,search,fields]{HistoryQuery q;q.search=search->text();q.from=fields["from"]->text();q.to=fields["to"]->text();q.mime=fields["mime"]->text();q.profileId=fields["profileId"]->text();q.uploadStatus=fields["uploadStatus"]->text();q.localStatus=fields["localStatus"]->text();q.remoteStatus=fields["remoteStatus"]->text();model_->setQuery(q);};connect(filter,&QPushButton::clicked,this,apply);connect(search,&QLineEdit::returnPressed,this,apply);connect(previous,&QPushButton::clicked,this,[this]{auto q=model_->query();q.offset=qMax(0,q.offset-q.limit);model_->setQuery(q);});connect(next,&QPushButton::clicked,this,[this]{auto q=model_->query();if(q.offset+q.limit<model_->total()){q.offset+=q.limit;model_->setQuery(q);}});connect(refreshButton,&QPushButton::clicked,this,&HistoryWindow::refresh);
 details_=new QPlainTextEdit(this);details_->setObjectName("historyDetails");details_->setReadOnly(true);details_->setMaximumHeight(180);layout->addWidget(details_);preview_=new QLabel(this);preview_->setObjectName("historyPreview");layout->addWidget(preview_);status_=new QLabel(this);status_->setWordWrap(true);layout->addWidget(status_);auto* buttons=new QGridLayout;layout->addLayout(buttons);
 copy_=new QPushButton("Copy stored link",this);copy_->setObjectName("copyHistoryLink");open_=new QPushButton("Open stored link",this);open_->setObjectName("openHistoryLink");copy_->setEnabled(false);open_->setEnabled(false);buttons->addWidget(copy_,0,0);buttons->addWidget(open_,0,1);auto* remove=new QPushButton("Delete selected remote uploads…",this);remove->setObjectName("deleteHistoryRemote");buttons->addWidget(remove,1,0);auto* retry=new QPushButton("Retry deletion",this);buttons->addWidget(retry,1,1);auto* cancel=new QPushButton("Cancel deletion",this);buttons->addWidget(cancel,2,0);auto* clear=new QPushButton("Clear history records…",this);buttons->addWidget(clear,2,1);auto* cache=new QPushButton("Clean retry artifacts and previews…",this);buttons->addWidget(cache,3,0);
 connect(table_->selectionModel(),&QItemSelectionModel::selectionChanged,this,[this]{selectionChanged();});connect(model_,&HistoryModel::loaded,this,[this]{count_->setText(QString("%1 stored entries; page starts at %2. Browsing uses the local ledger.").arg(model_->total()).arg(model_->query().offset));selectionChanged();});connect(model_,&HistoryModel::error,status_,&QLabel::setText);
 connect(copy_,&QPushButton::clicked,this,[this]{auto ids=selectedIds();if(ids.size()!=1)return;history_.copyLink(ids.first(),[g=QPointer<HistoryWindow>(this)](Error e,QJsonObject){if(g)g->status_->setText(e?e.code+": "+e.message:"Stored link copied.");});});connect(open_,&QPushButton::clicked,this,[this]{auto rows=table_->selectionModel()->selectedRows();if(rows.size()==1&&model_->linkAvailable(rows.first().row()))QDesktopServices::openUrl(QUrl(model_->record(rows.first().row())["receipt"].toObject()["directUrl"].toString()));});connect(remove,&QPushButton::clicked,this,&HistoryWindow::prepareDelete);
 connect(retry,&QPushButton::clicked,this,[this]{if(deletionId_.isEmpty())return;history_.retryDelete(deletionId_,[g=QPointer<HistoryWindow>(this)](Error e,QJsonObject){if(g){g->status_->setText(e?e.message:"Deletion retry accepted.");if(!e)g->deletionTimer_->start();}});});connect(cancel,&QPushButton::clicked,this,[this]{if(deletionId_.isEmpty())return;history_.cancelDelete(deletionId_,[g=QPointer<HistoryWindow>(this)](Error e,QJsonObject){if(g)g->status_->setText(e?e.message:"Cancellation requested; already sent deletion cannot be rolled back.");});});
 connect(clear,&QPushButton::clicked,this,[this]{if(QMessageBox::question(this,"Clear history","Clear local history records? No remote objects or user-owned local copies will be removed.")!=QMessageBox::Yes)return;history_.clear([g=QPointer<HistoryWindow>(this)](Error e,QJsonObject){if(g){g->status_->setText(e?e.message:"History cleared; remote objects unchanged.");g->refresh();}});});connect(cache,&QPushButton::clicked,this,[this]{if(QMessageBox::question(this,"Clean artifacts","Clean eligible retry artifacts and image previews? Persistent history, remote objects, and local copies remain. Some cleaned artifacts cannot retry.")!=QMessageBox::Yes)return;operations_.cleanup([g=QPointer<HistoryWindow>(this)](Error e,QJsonObject){if(g)g->status_->setText(e?e.message:"Artifact cleanup completed.");});});deletionTimer_=new QTimer(this);deletionTimer_->setInterval(500);connect(deletionTimer_,&QTimer::timeout,this,&HistoryWindow::pollDeletion);connect(&operations_,&OperationService::changed,this,[this]{refresh();});connect(&operations_,&OperationService::initialized,this,[this]{refresh();});if(operations_.ready())refresh();else status_->setText("History is waiting for the resident journal to initialize.");}
void HistoryWindow::refresh(){if(!operations_.ready()){status_->setText("History is waiting for the resident journal to initialize.");return;}model_->refresh();}
QStringList HistoryWindow::selectedIds()const{QStringList ids;for(auto row:table_->selectionModel()->selectedRows())ids.append(model_->record(row.row())["id"].toString());return ids;}
void HistoryWindow::selectionChanged(){auto rows=table_->selectionModel()->selectedRows();bool available=rows.size()==1&&model_->linkAvailable(rows.first().row());copy_->setEnabled(available);open_->setEnabled(available);details_->clear();preview_->clear();const auto seq=++selectionRequest_;if(rows.size()!=1)return;auto record=model_->record(rows.first().row());deletionId_=record["deleteOperationId"].toString();history_.detail(record["id"].toString(),[g=QPointer<HistoryWindow>(this),seq](Error e,QJsonObject data){if(!g||g->selectionRequest_!=seq)return;if(e){g->status_->setText(e.message);return;}g->details_->setPlainText(QString::fromUtf8(QJsonDocument(data).toJson(QJsonDocument::Indented)));if(data["superseded"].toBool()||data["remoteStatus"]=="superseded")g->status_->setText("Superseded: this original stored link may serve replacement content. Deletion still targets the original receipt.");else g->status_->setText("Original receipt and independent upload/local/deletion outcomes shown above.");auto path=data["previewPath"].toString();g->preview_->setText("Preview unavailable — "+data["mime"].toString());if(path.isEmpty())return;auto image=std::make_shared<QImage>();g->operations_.background([path,image](Error&){QImageReader reader(path);auto size=reader.size();if(!QFileInfo(path).isFile()||QFileInfo(path).size()>8*1024*1024||!size.isValid()||qint64(size.width())*size.height()>16000000)return QJsonObject{};reader.setScaledSize(size.scaled(320,180,Qt::KeepAspectRatio));*image=reader.read();return QJsonObject{};},[g,seq,image](Error,QJsonObject){if(g&&seq==g->selectionRequest_&&!image->isNull())g->preview_->setPixmap(QPixmap::fromImage(*image));});});}
void HistoryWindow::prepareDelete(){auto ids=selectedIds();if(ids.isEmpty())return;history_.prepareDelete(ids,[g=QPointer<HistoryWindow>(this),ids](Error e,QJsonObject preview){if(!g)return;if(e){g->status_->setText(e.code+": "+e.message);return;}QString text="Delete these original recorded remote targets?\nLocal copies and history records remain. Browser/CDN caches may still serve bytes.\n";for(auto v:preview["targets"].toArray()){auto target=v.toObject();auto receipt=target["receipt"].toObject();text+="\nHistory ID: "+target["historyId"].toString()+"\nOriginal destination / exact target: "+QString::fromUtf8(QJsonDocument(receipt).toJson(QJsonDocument::Compact))+"\nEffect: "+target["effect"].toString()+"\n";}if(QMessageBox::question(g,"Confirm exact remote deletion",text,QMessageBox::Yes|QMessageBox::Cancel,QMessageBox::Cancel)!=QMessageBox::Yes)return;g->history_.deleteConfirmed(ids,preview["acknowledgement"].toString(),[g](Error failure,QJsonObject data){if(!g)return;g->status_->setText(failure?failure.code+": "+failure.message:"Remote deletion accepted; individual outcomes will update.");if(!failure){g->deletionId_=data["deleteOperationId"].toString();g->deletionTimer_->start();}});});}
void HistoryWindow::pollDeletion(){if(deletionPollActive_)return;if(deletionId_.isEmpty()){deletionTimer_->stop();return;}deletionPollActive_=true;const auto id=deletionId_;history_.inspectDelete(id,[g=QPointer<HistoryWindow>(this),id](Error e,QJsonObject data){if(!g)return;g->deletionPollActive_=false;if(g->deletionId_!=id)return;if(e){g->status_->setText(e.message);g->deletionTimer_->stop();return;}QString status="Deletion "+data["id"].toString()+": "+data["state"].toString();for(auto v:data["items"].toArray()){auto item=v.toObject();status+="\n"+item["historyId"].toString()+": "+item["status"].toString()+" "+item["error"].toObject()["message"].toString();}g->status_->setText(status);if(data["state"]!="running"&&data["state"]!="accepted"){g->deletionTimer_->stop();g->refresh();}});}
}
